  1	/**
  2	 * Route Table Structure Tests
  3	 *
  4	 * WP-005: Validates the structural invariants of the unified route table
  5	 * returned by `buildRoutes()` in gui/server.ts to prevent regressions when
  6	 * adding future routes.
  7	 *
  8	 * Invariants verified:
  9	 *  1. Every route entry has a `method` value from the set {GET, POST, PUT, PATCH, DELETE}.
 10	 *  2. Every RegExp route uses only named capture groups — no positional (unnamed) groups.
 11	 *  3. No two routes share the same `method + path` combination (exact string or RegExp source).
 12	 */
 13	
 14	import { describe, it, expect } from 'vitest';
 15	
 16	import { buildRoutes, HttpMethod } from '../../gui/server.js';
 17	
 18	// ---------------------------------------------------------------------------
 19	// Fixture: minimal dummy arguments — we are inspecting structure, not executing handlers
 20	// ---------------------------------------------------------------------------
 21	
 22	const DUMMY_LEDGER_ROOT = '/tmp/ledger';
 23	const DUMMY_CONFIG_PATH = '/tmp/config.json';
 24	const DUMMY_LOGS_DIR    = '/tmp/logs';
 25	const DUMMY_BOOT_VERSIONS = null;
 26	
 27	const routes = buildRoutes(
 28	  DUMMY_LEDGER_ROOT,
 29	  DUMMY_CONFIG_PATH,
 30	  DUMMY_LOGS_DIR,
 31	  DUMMY_BOOT_VERSIONS,
 32	);
 33	
 34	// ---------------------------------------------------------------------------
 35	// Helper: extract the "path key" used for duplicate detection
 36	// ---------------------------------------------------------------------------
 37	
 38	function pathKey(path: string | RegExp): string {
 39	  return typeof path === 'string' ? path : path.source;
 40	}
 41	
 42	// ---------------------------------------------------------------------------
 43	// Tests
 44	// ---------------------------------------------------------------------------
 45	
 46	describe('buildRoutes() — route table structural invariants', () => {
 47	
 48	  it('returns a non-empty array', () => {
 49	    expect(Array.isArray(routes)).toBe(true);
 50	    expect(routes.length).toBeGreaterThan(0);
 51	  });
 52	
 53	  it('every route has a valid HTTP method (GET, POST, PUT, PATCH, DELETE)', () => {
 54	    // The HttpMethod union type in server.ts enforces this constraint at compile
 55	    // time. This runtime test serves as defense-in-depth — it guards against
 56	    // future changes that might accidentally widen the type or cast around it.
 57	    const VALID_METHODS = new Set<HttpMethod>(['GET', 'POST', 'PUT', 'PATCH', 'DELETE']);
 58	
 59	    const violations = routes.filter(
 60	      (route) => !VALID_METHODS.has(route.method),
 61	    );
 62	
 63	    expect(violations).toEqual([]);
 64	  });
 65	
 66	  it('every RegExp route uses only named capture groups — no positional (unnamed) groups', () => {
 67	    /**
 68	     * A positional (unnamed) capture group is an opening parenthesis `(` that is
 69	     * NOT followed by either:
 70	     *   - `?:` — non-capturing group
 71	     *   - `?<` — named capture group
 72	     *   - `?=` — positive lookahead
 73	     *   - `?!` — negative lookahead
 74	     *   - `?<=` — positive lookbehind
 75	     *   - `?<!` — negative lookbehind
 76	     *
 77	     * The regex below detects any `(` that does NOT start one of the above
 78	     * special-group syntaxes (i.e., it is a plain capturing group).
 79	     */
 80	    const POSITIONAL_GROUP_RE = /\((?!\?)/;
 81	
 82	    const violations = routes.filter((route) => {
 83	      if (typeof route.path !== 'object') return false;   // skip string routes
 84	      return POSITIONAL_GROUP_RE.test(route.path.source);
 85	    });
 86	
 87	    const violatingPatterns = violations.map((r) => ({
 88	      method: r.method,
 89	      source: (r.path as RegExp).source,
 90	    }));
 91	
 92	    expect(violatingPatterns).toEqual([]);
 93	  });
 94	
 95	  it('no two routes share the same method + path combination', () => {
 96	    const seen = new Map<string, number>();   // key → first index
 97	    const duplicates: Array<{ index: number; method: string; path: string }> = [];
 98	
 99	    routes.forEach((route, idx) => {
100	      const key = `${route.method} ${pathKey(route.path)}`;

101	  const idx = args.indexOf('--port');
102	  if (idx !== -1 && idx + 1 < args.length) {
103	    const p = parseInt(args[idx + 1]!, 10);
104	    if (!isNaN(p) && p > 0) return p;
105	  }
106	  return 3420;
107	}
108	
109	// ---------------------------------------------------------------------------
110	// MIME types
111	// ---------------------------------------------------------------------------
112	
113	const MIME_TYPES: Record<string, string> = {
114	  '.html': 'text/html',
115	  '.css': 'text/css',
116	  '.js': 'application/javascript',
117	};
118	
119	// ---------------------------------------------------------------------------
120	// CORS helpers
121	// ---------------------------------------------------------------------------
122	
123	function corsHeaders(port: number): Record<string, string> {
124	  return {
125	    'Access-Control-Allow-Origin': `http://localhost:${port}`,
126	    'Access-Control-Allow-Methods': 'GET, POST, PUT, PATCH, DELETE, OPTIONS',
127	    'Access-Control-Allow-Headers': 'Content-Type',
128	  };
129	}
130	
131	// ---------------------------------------------------------------------------
132	// Security headers
133	// ---------------------------------------------------------------------------
134	
135	function securityHeaders(): Record<string, string> {
136	  return {
137	    'X-Content-Type-Options': 'nosniff',
138	    'X-Frame-Options': 'DENY',
139	    'Referrer-Policy': 'strict-origin-when-cross-origin',
140	    'Content-Security-Policy':
141	      "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'",
142	  };
143	}
144	
145	// ---------------------------------------------------------------------------
146	// Response helpers
147	// ---------------------------------------------------------------------------
148	
149	function sendJson(
150	  res: ServerResponse,
151	  status: number,
152	  data: unknown,
153	  port: number
154	): void {
155	  const body = JSON.stringify(data);
156	  res.writeHead(status, {
157	    'Content-Type': 'application/json',
158	    'Content-Length': Buffer.byteLength(body),
159	    ...corsHeaders(port),
160	    ...securityHeaders(),
161	  });
162	  res.end(body);
163	}
164	
165	function sendError(
166	  res: ServerResponse,
167	  status: number,
168	  code: string,
169	  message: string,
170	  port: number
171	): void {
172	  sendJson(res, status, { error: { code, message } }, port);
173	}
174	
175	export function apiErrorToStatus(code: string): number {
176	  switch (code) {
177	    case 'NOT_FOUND':
178	      return 404;
179	    case 'FORBIDDEN':
180	      return 403;
181	    case 'VALIDATION_ERROR':
182	      return 400;
183	    case 'CONFLICT':
184	      return 409;
185	    default:
186	      return 500;
187	  }
188	}
189	
190	// ---------------------------------------------------------------------------
191	// Body reading
192	// ---------------------------------------------------------------------------
193	
194	/** Maximum accepted request body size (1 MiB). */
195	export const MAX_BODY_BYTES = 1_048_576;
196	
197	/** Thrown by {@link readBody} when the request body exceeds {@link MAX_BODY_BYTES}. */
198	export class PayloadTooLargeError extends Error {
199	  constructor() {
200	    super('Payload Too Large');
201	    this.name = 'PayloadTooLargeError';
202	  }
203	}
204	
205	/**
206	 * Reads the full request body as a UTF-8 string, enforcing a size limit of
207	 * {@link MAX_BODY_BYTES} (1 MiB).
208	 *
209	 * @throws {PayloadTooLargeError} When the body exceeds the limit (detected
210	 *   either via Content-Length header pre-check or streaming byte count).
211	 *   **Callers must catch this error and return a 413 response.**
212	 *
213	 * @param req - The incoming HTTP request.
214	 * @returns The full body string.
215	 */
216	function readBody(req: IncomingMessage): Promise<string> {
217	  return new Promise((resolve, reject) => {
218	    // Content-Length pre-check: reject immediately if the declared size exceeds the limit.
219	    const declaredLength = req.headers['content-length'];
220	    if (declaredLength !== undefined) {
221	      const n = parseInt(declaredLength, 10);
222	      if (!isNaN(n) && n > MAX_BODY_BYTES) {
223	        req.resume();  // drain body data from socket buffer
224	        reject(new PayloadTooLargeError());
225	        return;
226	      }
227	    }
228	
229	    const chunks: Buffer[] = [];
230	    let totalBytes = 0;
231	    let rejected = false;
232	
233	    req.on('data', (chunk: Buffer) => {
234	      if (rejected) return;
235	      totalBytes += chunk.length;
236	      if (totalBytes > MAX_BODY_BYTES) {
237	        rejected = true;
238	        reject(new PayloadTooLargeError());
239	        // Drain remaining data so the 413 response can be sent cleanly.
240	        req.resume();
241	        return;
242	      }
243	      chunks.push(chunk);
244	    });
245	    req.on('end', () => {
246	      if (!rejected) resolve(Buffer.concat(chunks).toString('utf-8'));
247	    });
248	    req.on('error', (err) => {
249	      if (!rejected) reject(err);
250	    });
251	  });
252	}
253	
254	/**
255	 * Reads and parses the request body as JSON, enforcing the same size limit as
256	 * {@link readBody}. Throws {@link PayloadTooLargeError} for oversized bodies
257	 * and {@link ApiError} with code `VALIDATION_ERROR` for invalid JSON.
258	 *
259	 * @param req - The incoming HTTP request.
260	 * @returns The parsed JSON value.
261	 */
262	async function readJsonBody(req: IncomingMessage): Promise<unknown> {
263	  const raw = await readBody(req);
264	  try {
265	    return JSON.parse(raw);
266	  } catch {
267	    throw new ApiError('VALIDATION_ERROR', 'Invalid JSON body.');
268	  }
269	}
270	
271	// ---------------------------------------------------------------------------
272	// Router
273	// ---------------------------------------------------------------------------
274	
275	/**
276	 * The set of HTTP methods accepted by the route dispatcher.
277	 *
278	 * Narrowing `Route.method` to this union converts a previously runtime-only
279	 * validation (enforced by `route-table.test.ts`) into a compile-time guarantee.
280	 * The test continues to serve as defense-in-depth.
281	 */
282	export type HttpMethod = 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE';
283	
284	/**
285	 * A declarative body-parsing route entry for {@link buildRoutes} and
286	 * {@link dispatchRoute}.
287	 *
288	 * - `method` — HTTP method; must be one of the {@link HttpMethod} values
289	 *   (`GET`, `POST`, `PUT`, `PATCH`, `DELETE`, uppercase). The union type
290	 *   enforces this at compile time; `route-table.test.ts` provides
291	 *   defense-in-depth at test time.
292	 * - `path` — Exact string path or a RegExp with named capture groups.
293	 * - `handler` — Receives the parsed body (or `undefined` when `noBody` is
294	 *   set), any named capture groups extracted from the RegExp match, and the
295	 *   parsed query parameters from the request URL.
296	 * - `statusCode` — Response status code (default `200`). Use `204` for empty
297	 *   responses — the dispatcher writes the header and skips `sendJson()`.
298	 * - `noBody` — When `true`, skip `readJsonBody()`.
299	 */
300	export interface Route {

101	      if (seen.has(key)) {
102	        duplicates.push({ index: idx, method: route.method, path: pathKey(route.path) });
103	      } else {
104	        seen.set(key, idx);
105	      }
106	    });
107	
108	    expect(duplicates).toEqual([]);
109	  });
110	
111	});

1101	 */
1102	export async function dispatchRoute(
1103	  req: IncomingMessage,
1104	  res: ServerResponse,
1105	  method: string,
1106	  url: string,
1107	  port: number,
1108	  routes: Route[]
1109	): Promise<boolean> {
1110	  const [path] = url.split('?') as [string];
1111	  const query = parseQueryString(url);
1112	  for (const route of routes) {
1113	    if (route.method !== method) continue;
1114	    let groups: Record<string, string> | undefined;
1115	    if (typeof route.path === 'string') {
1116	      if (route.path !== path) continue;
1117	    } else {
1118	      const m = route.path.exec(path);
1119	      if (!m) continue;
1120	      groups = (m.groups ?? {}) as Record<string, string>;
1121	    }
1122	    try {
1123	      const body = route.noBody ? undefined : await readJsonBody(req);
1124	      const result = await route.handler(body, groups, query);
1125	      if (route.statusCode === 204) {
1126	        res.writeHead(204, { ...corsHeaders(port), ...securityHeaders() });
1127	        res.end();
1128	      } else {
1129	        sendJson(res, route.statusCode ?? 200, result, port);
1130	      }
1131	    } catch (err) {
1132	      if (err instanceof PayloadTooLargeError) {
1133	        sendError(res, 413, 'PAYLOAD_TOO_LARGE', 'Payload Too Large.', port);
1134	      } else if (err instanceof ApiError) {
1135	        sendError(res, apiErrorToStatus(err.code), err.code, err.message, port);
1136	      } else {
1137	        process.stderr.write(
1138	          `[server] Unhandled error in ${method} ${path}: ${String(err)}\n`
1139	        );
1140	        sendError(res, 500, 'INTERNAL_ERROR', 'An unexpected error occurred.', port);
1141	      }
1142	    }
1143	    return true;
1144	  }
1145	  return false;
1146	}
1147	
1148	// ---------------------------------------------------------------------------
1149	// Main request handler
1150	// ---------------------------------------------------------------------------
1151	
1152	export async function handleRequest(
1153	  req: IncomingMessage,
1154	  res: ServerResponse,
1155	  ledgerRoot: string,
1156	  configPath: string,
1157	  port: number,
1158	  orchestratorLogsDir: string,
1159	  bootVersions: WorkspaceVersions | null = null
1160	): Promise<void> {
1161	  const method = req.method?.toUpperCase() ?? 'GET';
1162	  const url = req.url ?? '/';
1163	  const [path] = url.split('?') as [string];
1164	  const segments = path.split('/').filter(Boolean);
1165	  const isApiRequest = segments[0] === 'api';
1166	
1167	  // OPTIONS preflight
1168	  if (method === 'OPTIONS') {
1169	    res.writeHead(200, { ...corsHeaders(port), ...securityHeaders() });
1170	    res.end();
1171	    return;
1172	  }
1173	
1174	  // Static files
1175	  if (!isApiRequest) {
1176	    await serveStatic(req, res, port);
1177	    return;
1178	  }
1179	
1180	  // All API traffic is dispatched via the unified declarative route table.

